parameters.jsCode:
const items = $input.all();
const fechaHoy = new Date().toLocaleString('es-CO', { timeZone: 'America/Bogota' });
const msgRaw = $('Telegram Trigger: Mensaje Entrante1').first().json.message;
const textoAndres = msgRaw.text || '¿Qué citas tengo?';

const citasConfirmadas = [];
const citasCanceladas = [];

for (const it of items) {
  const j = it.json;
  if (!j || !j.cita_id) continue;
  const st = (j.estado || 'confirmada').toString().trim().toLowerCase();
  const c = {
    ref: '#' + (j.ref_corta || j.cita_id.slice(0, 8)),
    cliente: j.cliente || 'Cliente',
    wa_id: (j.wa_id || '').toString().trim(),
    servicio: j.servicio || 'Servicio',
    fecha_cita: j.fecha_cita,
    fecha_humana: j.fecha_humana,
    hora_fin: j.hora_fin,
    precio: Number(j.precio || 0),
    estado: st === 'cancelada' ? 'Cancelada' : 'Confirmada'
  };
  if (st === 'cancelada') {
    citasCanceladas.push(c);
  } else {
    citasConfirmadas.push(c);
  }
}

return [{
  json: {
    chat_id: msgRaw.chat.id,
    pregunta_andres: textoAndres,
    fecha_actual: fechaHoy,
    citas_activas: citasConfirmadas,
    citas_canceladas: citasCanceladas,
    resumen_citas_activas_texto: JSON.stringify(citasConfirmadas, null, 2),
    resumen_citas_canceladas_texto: JSON.stringify(citasCanceladas, null, 2)
  }
}];

